def dinuc_shuffle(seq: str, rng) -> str:
    """Altschul-Erickson dinucleotide shuffle.

    Builds an Eulerian path on the de Bruijn graph of dinucleotides; result
    preserves single-nucleotide and dinucleotide composition exactly.
    """
    if len(seq) < 2:
        return seq
    # adjacency: from nucleotide -> list of next nucleotides
    edges = defaultdict(list)
    for i in range(len(seq) - 1):
        edges[seq[i]].append(seq[i + 1])

    # randomize edge order
    for k in edges:
        rng.shuffle(edges[k])

    last = seq[-1]
    # For each non-last node, randomly pick one outgoing edge as the "last" edge
    # used by the Eulerian tour. Standard A-E construction.
    last_edges = {}
    nodes = set(edges.keys()) | {last}
    for n in nodes:
        if n == last:
            continue
        if edges.get(n):
            last_edges[n] = edges[n].pop()  # reserve one edge

    # Re-shuffle remaining edges, then re-append the reserved last edge
    for n in nodes:
        if n == last:
            continue
        if n in last_edges:
            rng.shuffle(edges[n])
            edges[n].append(last_edges[n])

    # Walk the path
    out = [seq[0]]
    cur = seq[0]
    for _ in range(len(seq) - 1):
        if not edges.get(cur):
            # graph dead end (rare). Bail and use simple shuffle.
            chars = list(seq)
            rng.shuffle(chars)
            return "".join(chars)
        nxt = edges[cur].pop(0)
        out.append(nxt)
        cur = nxt
    return "".join(out)

